   269  static int
   270  json_parse_number(const unsigned char **ucp, const unsigned char *ue,
   271      size_t lvl __file_debugused)
   272  {
   273          const unsigned char *uc = *ucp;
   274          int got = 0;
   275
   276          DPRINTF("Parse number: ", uc, *ucp);
   277          if (uc == ue)
   278                  return 0;
   279          if (*uc == '-')
   280                  uc++;
   281
   282          for (; uc < ue; uc++) {
   283                  if (!json_isdigit(*uc))
   284                          break;
   285                  got = 1;
   286          }
   287          if (uc == ue)
   288                  goto out;
   289          if (*uc == '.')
   290                  uc++;
   291          for (; uc < ue; uc++) {
   292                  if (!json_isdigit(*uc))
   293                          break;
   294                  got = 1;
   295          }
   296          if (uc == ue)
   297                  goto out;
   298          if (got && (*uc == 'e' || *uc == 'E')) {
   299                  uc++;
   300                  got = 0;
   301                  if (uc == ue)
   302                          goto out;
   303                  if (*uc == '+' || *uc == '-')
   304                          uc++;
   305                  for (; uc < ue; uc++) {
   306                          if (!json_isdigit(*uc))
   307                                  break;
   308                          got = 1;
   309                  }
   310          }
   311  out:
   312          if (!got)
   313                  DPRINTF("Bad number: ", uc, *ucp);
   314          else
   315                  DPRINTF("Good number: ", uc, *ucp);
   316          *ucp = uc;
   317          return got;
   318  }
