   320  static int
   321  json_parse_const(const unsigned char **ucp, const unsigned char *ue,
   322      const char *str, size_t len, size_t lvl __file_debugused)
   323  {
   324          const unsigned char *uc = *ucp;
   325
   326          DPRINTF("Parse const: ", uc, *ucp);
   327          for (len--; uc < ue && --len;) {
   328                  if (*uc++ == *++str)
   329                          continue;
   330          }
   331          if (len)
   332                  DPRINTF("Bad const: ", uc, *ucp);
   333          *ucp = uc;
   334          return len == 0;
   335  }
   336
   337  static int
   338  json_parse(const unsigned char **ucp, const unsigned char *ue,
   339      size_t *st, size_t lvl)
   340  {
   341          const unsigned char *uc;
   342          int rv = 0;
   343          int t;
   344
   345          uc = json_skip_space(*ucp, ue);
   346          if (uc == ue)
   347                  goto out;
   348
   349          // Avoid recursion
   350          if (lvl > 500) {
   351                  DPRINTF("Too many levels", uc, *ucp);
   352                  return 0;
   353          }
   354  #if JSON_COUNT
   355          /* bail quickly if not counting */
   356          if (lvl > 1 && (st[JSON_OBJECT] || st[JSON_ARRAYN]))
   357                  return 1;
   358  #endif
   359
   360          DPRINTF("Parse general: ", uc, *ucp);
